import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    degree = [len(adj[v]) for v in range(n)]
    adj_sets = [set(a) for a in adj]

    def dsatur_color(noise=0.0):
        colors = [-1] * n
        sat = [0] * n
        nc = [set() for _ in range(n)]
        uncolored = set(range(n))
        while uncolored:
            if noise > 0:
                best = max(uncolored, key=lambda v: (sat[v], degree[v], random.random()))
            else:
                best = max(uncolored, key=lambda v: (sat[v], degree[v]))
            c = 0
            while c in nc[best]:
                c += 1
            colors[best] = c
            uncolored.remove(best)
            for u in adj[best]:
                if colors[u] == -1 and c not in nc[u]:
                    nc[u].add(c)
                    sat[u] += 1
        return colors

    def rlf_color():
        colors = [-1] * n
        cur = 0
        uncolored = set(range(n))
        while uncolored:
            candidates = set(uncolored)
            excluded = set()
            iset = []
            start = max(candidates, key=lambda v: sum(1 for u in adj[v] if u in uncolored))
            iset.append(start)
            candidates.discard(start)
            for u in adj[start]:
                if u in candidates:
                    candidates.discard(u)
                    excluded.add(u)
            while candidates:
                v = max(candidates, key=lambda x: (
                    sum(1 for u in adj[x] if u in excluded),
                    -sum(1 for u in adj[x] if u in candidates)
                ))
                iset.append(v)
                candidates.discard(v)
                for u in adj[v]:
                    if u in candidates:
                        candidates.discard(u)
                        excluded.add(u)
            for v in iset:
                colors[v] = cur
                uncolored.discard(v)
            cur += 1
        return colors

    def kempe_reduce(colors):
        colors = colors[:]
        improved = True
        passes = 0
        while improved and passes < 40:
            improved = False
            passes += 1
            num_colors = max(colors) + 1
            if num_colors <= 1:
                break
            max_c = num_colors - 1
            high_verts = [v for v in range(n) if colors[v] == max_c]
            if not high_verts:
                break
            all_placed = True
            for v in high_verts:
                if colors[v] != max_c:
                    continue
                forbidden = {colors[u] for u in adj[v]}
                placed = False
                for c in range(max_c):
                    if c not in forbidden:
                        colors[v] = c
                        placed = True
                        improved = True
                        break
                if placed:
                    continue
                swapped = False
                lower = list(range(max_c))
                random.shuffle(lower)
                for c in lower:
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    chain = []
                    while stack:
                        u = stack.pop()
                        chain.append(u)
                        for w in adj[u]:
                            if w not in visited and colors[w] in (max_c, c):
                                visited.add(w)
                                stack.append(w)
                    for u in chain:
                        colors[u] = c if colors[u] == max_c else max_c
                    if colors[v] != max_c:
                        swapped = True
                        improved = True
                        break
                    else:
                        for u in chain:
                            colors[u] = max_c if colors[u] == c else c
                if not swapped:
                    all_placed = False
            if not all_placed:
                break
        return colors

    def squeeze_last(colors):
        """Try to eliminate the highest color by reassigning vertices."""
        colors = colors[:]
        num_colors = max(colors) + 1
        max_c = num_colors - 1
        high_verts = [v for v in range(n) if colors[v] == max_c]
        # Try to recolor each high vertex by temporarily uncoloring neighbors
        for v in sorted(high_verts, key=lambda x: degree[x]):
            if colors[v] != max_c:
                continue
            forbidden = {colors[u] for u in adj[v]}
            # Try direct recolor
            for c in range(max_c):
                if c not in forbidden:
                    colors[v] = c
                    break
            if colors[v] != max_c:
                continue
            # Try swapping one neighbor to free a color
            for u in adj[v]:
                cu = colors[u]
                if cu >= max_c:
                    continue
                # Try to recolor u to something else
                fu = {colors[w] for w in adj[u] if w != v}
                for c2 in range(max_c):
                    if c2 not in fu and c2 != max_c:
                        colors[u] = c2
                        forbidden2 = {colors[w] for w in adj[v]}
                        if cu not in forbidden2:
                            colors[v] = cu
                            break
                        else:
                            colors[u] = cu
                if colors[v] != max_c:
                    break
        return colors

    best_colors = None
    best_count = float('inf')

    def update_best(c):
        nonlocal best_colors, best_count
        cnt = max(c) + 1
        if cnt < best_count:
            best_count = cnt
            best_colors = c[:]

    # Phase 1: Initial constructions
    update_best(dsatur_color(noise=0.0))
    update_best(rlf_color())
    for _ in range(3):
        update_best(dsatur_color(noise=1.0))

    # Phase 2: Kempe reduce best
    reduced = kempe_reduce(best_colors)
    update_best(reduced)

    # Phase 3: Restarts with Kempe
    for _ in range(5):
        c = dsatur_color(noise=1.0)
        c = kempe_reduce(c)
        update_best(c)

    # Phase 4: RLF with Kempe
    c = rlf_color()
    c = kempe_reduce(c)
    update_best(c)

    # Phase 5: Squeeze attempts on best
    for _ in range(3):
        c = squeeze_last(best_colors[:])
        c = kempe_reduce(c)
        update_best(c)

    return best_colors
